    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address u1, address u2, uint amount) public payable {
        require(u1 != address(0) && u2 != address(0));
        require(u1 != u2);

        uint b1 = c.getBalance(u1); if (__ESBMC_reverted()) return;
